export const ZITATE=[{id:'z1',zitat:'Ich weiß, dass ich nichts weiß.',autor:'sokrates',name:'Sokrates',themen:['Erkenntnistheorie'],situationen:['Sinnsuche & Zweifel']},{id:'z2',zitat:'Der Mensch ist ein zoon politikon – ein von Natur aus politisches Lebewesen.',autor:'aristoteles',name:'Aristoteles',themen:['Politische Philosophie'],situationen:['Einsamkeit']},{id:'z3',zitat:'Cogito ergo sum – Ich denke, also bin ich.',autor:'descartes',name:'René Descartes',themen:['Erkenntnistheorie','Rationalismus'],situationen:['Angst & Unsicherheit']},{id:'z4',zitat:'Der Mensch ist zur Freiheit verurteilt.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Entscheidungen treffen']},{id:'z5',zitat:'Gott ist tot. Und wir haben ihn getötet.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus','Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z6',zitat:'Handle nur nach derjenigen Maxime, durch die du zugleich wollen kannst, dass sie ein allgemeines Gesetz werde.',autor:'kant',name:'Immanuel Kant',themen:['Ethik'],situationen:['Entscheidungen treffen']},{id:'z7',zitat:'Die Philosophen haben die Welt nur verschieden interpretiert; es kommt darauf an, sie zu verändern.',autor:'marx',name:'Karl Marx',themen:['Politische Philosophie'],situationen:['Veränderung & Neuanfang']},{id:'z8',zitat:'Der Tod ist nichts für uns, denn solange wir sind, ist der Tod nicht da; und ist der Tod da, sind wir nicht mehr.',autor:'epikur',name:'Epikur',themen:['Ethik'],situationen:['Tod & Vergänglichkeit']},{id:'z9',zitat:'Nicht die Dinge selbst beunruhigen die Menschen, sondern ihre Meinungen über die Dinge.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus','Ethik'],situationen:['Stress & Überforderung','Angst & Unsicherheit']},{id:'z10',zitat:'Der Mensch ist des Menschen Wolf.',autor:'hobbes',name:'Thomas Hobbes',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z11',zitat:'Wo Macht ist, ist Widerstand.',autor:'foucault',name:'Michel Foucault',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z12',zitat:'Die Banalität des Bösen zeigt sich nicht im Monster, sondern im Gehorsam des Gewöhnlichen.',autor:'arendt',name:'Hannah Arendt',themen:['Ethik','Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z13',zitat:'Man kann nicht zweimal in denselben Fluss steigen.',autor:'heraklit',name:'Heraklit',themen:['Metaphysik'],situationen:['Veränderung & Neuanfang']},{id:'z14',zitat:'Der Mensch ist frei geboren, und überall liegt er in Ketten.',autor:'rousseau',name:'Jean-Jacques Rousseau',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z15',zitat:'Wir sind wie Stachelschweine, die einander wärmen wollen, ohne sich zu stechen.',autor:'schopenhauer',name:'Arthur Schopenhauer',themen:['Ethik','Metaphysik'],situationen:['Liebe & Beziehungen','Einsamkeit']},{id:'z16',zitat:'Das Leben kann nur rückwärts verstanden werden, muss aber vorwärts gelebt werden.',autor:'kierkegaard',name:'Søren Kierkegaard',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel','Entscheidungen treffen']},{id:'z17',zitat:'Man muss sich Sisyphos als einen glücklichen Menschen vorstellen.',autor:'camus',name:'Albert Camus',themen:['Existentialismus','Ethik'],situationen:['Scheitern & Rückschläge']},{id:'z18',zitat:'Wovon man nicht sprechen kann, darüber muss man schweigen.',autor:'wittgenstein',name:'Ludwig Wittgenstein',themen:['Sprachphilosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z19',zitat:'Ich suche einen Menschen.',autor:'diogenes',name:'Diogenes von Sinope',themen:['Ethik'],situationen:['Einsamkeit']},{id:'z20',zitat:'Der Mensch ist das Maß aller Dinge.',autor:'protagoras',name:'Protagoras',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z21',zitat:'Nichts existiert außer Atomen und leerem Raum, alles andere ist Meinung.',autor:'demokrit',name:'Demokrit',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z22',zitat:'War ich eben ein Mensch, der von einem Schmetterling träumte, oder bin ich jetzt ein Schmetterling, der von einem Menschen träumt?',autor:'zhuangzi',name:'Zhuangzi',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z23',zitat:'Was du selbst nicht wünschst, das tue auch keinem anderen an.',autor:'konfuzius',name:'Konfuzius',themen:['Ethik'],situationen:['Liebe & Beziehungen']},{id:'z24',zitat:'Das Herz hat seine Gründe, die die Vernunft nicht kennt.',autor:'pascal',name:'Blaise Pascal',themen:['Ethik'],situationen:['Liebe & Beziehungen']},{id:'z25',zitat:'Wissen ist Macht.',autor:'bacon',name:'Francis Bacon',themen:['Erkenntnistheorie'],situationen:['Entscheidungen treffen']},{id:'z26',zitat:'Zu den Sachen selbst!',autor:'husserl',name:'Edmund Husserl',themen:['Phänomenologie'],situationen:['Sinnsuche & Zweifel']},{id:'z27',zitat:'Man kommt nicht als Frau zur Welt, man wird es.',autor:'beauvoir',name:'Simone de Beauvoir',themen:['Feminismus','Existentialismus'],situationen:['Selbstzweifel & Kritik']},{id:'z28',zitat:'Die menschliche Natur ist von Grund auf gut.',autor:'mengzi',name:'Menzius (Mengzi)',themen:['Ethik'],situationen:['Selbstzweifel & Kritik']},{id:'z29',zitat:'Du hast Macht über deinen Geist – nicht über äußere Ereignisse. Erkenne dies, und du wirst Stärke finden.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Angst & Unsicherheit','Stress & Überforderung']},{id:'z30',zitat:'Die Hindernisse auf dem Weg werden zum Weg selbst.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Scheitern & Rückschläge']},{id:'z31',zitat:'Es ist nicht, dass wir wenig Zeit haben, sondern dass wir viel davon verschwenden.',autor:'seneca',name:'Seneca',themen:['Stoizismus','Ethik'],situationen:['Stress & Überforderung']},{id:'z32',zitat:'Es liegt nicht in unserer Macht, was uns widerfährt, wohl aber, wie wir damit umgehen.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Angst & Unsicherheit','Scheitern & Rückschläge']},{id:'z33',zitat:'Mitten im Winter fand ich schließlich, dass in mir ein unbesiegbarer Sommer lag.',autor:'camus',name:'Albert Camus',themen:['Existentialismus'],situationen:['Trauer & Verlust','Scheitern & Rückschläge']},{id:'z34',zitat:'Was mich nicht umbringt, macht mich stärker.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Scheitern & Rückschläge']},{id:'z35',zitat:'Angst ist der Schwindel der Freiheit.',autor:'kierkegaard',name:'Søren Kierkegaard',themen:['Existentialismus'],situationen:['Angst & Unsicherheit']},{id:'z36',zitat:'Eine Reise von tausend Meilen beginnt mit einem einzigen Schritt.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Veränderung & Neuanfang']},{id:'z37',zitat:'Es spielt keine Rolle, wie langsam du gehst, solange du nicht stehenbleibst.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Scheitern & Rückschläge']},{id:'z38',zitat:'Die Hölle, das sind die anderen.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Liebe & Beziehungen','Einsamkeit']},{id:'z39',zitat:'Niemand hat das Recht zu gehorchen.',autor:'arendt',name:'Hannah Arendt',themen:['Politische Philosophie','Ethik'],situationen:['Wut & Ungerechtigkeit']},{id:'z40',zitat:'Ihr selbst müsst euch bemühen; die Buddhas zeigen nur den Weg.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Entscheidungen treffen','Veränderung & Neuanfang']},{id:'z41',zitat:'Der Geist ist alles. Was du denkst, wirst du.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Selbstzweifel & Kritik']},{id:'z42',zitat:'Der Wechsel allein ist das Beständige.',autor:'schopenhauer',name:'Arthur Schopenhauer',themen:['Metaphysik'],situationen:['Veränderung & Neuanfang']},{id:'z43',zitat:'Die größte Strafe für die Weigerung, sich an der Politik zu beteiligen, ist es, von schlechteren Menschen regiert zu werden.',autor:'platon',name:'Platon',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z44',zitat:'Ich habe mich bemüht, die menschlichen Handlungen nicht zu belachen, nicht zu beklagen, noch zu verabscheuen, sondern zu verstehen.',autor:'spinoza',name:'Baruch de Spinoza',themen:['Rationalismus','Ethik'],situationen:['Wut & Ungerechtigkeit','Sinnsuche & Zweifel']},{id:'z45',zitat:'Kein Wissen des Menschen kann über seine Erfahrung hinausgehen.',autor:'locke',name:'John Locke',themen:['Empirismus'],situationen:['Entscheidungen treffen']},{id:'z46',zitat:'Diejenigen, die dich dazu bringen können, Absurditäten zu glauben, können dich dazu bringen, Gräueltaten zu begehen.',autor:'voltaire',name:'Voltaire',themen:['Politische Philosophie','Ethik'],situationen:['Wut & Ungerechtigkeit']},{id:'z47',zitat:'Die Vernunft ist und sollte nur die Sklavin der Leidenschaften sein.',autor:'hume',name:'David Hume',themen:['Empirismus'],situationen:['Entscheidungen treffen']},{id:'z48',zitat:'Die Eule der Minerva beginnt erst mit der einbrechenden Dämmerung ihren Flug.',autor:'hegel',name:'G.W.F. Hegel',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z49',zitat:'Über sich selbst, über seinen eigenen Körper und Geist, ist der Einzelne souverän.',autor:'mill',name:'John Stuart Mill',themen:['Utilitarismus','Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z50',zitat:'Die Sprache ist das Haus des Seins.',autor:'heidegger',name:'Martin Heidegger',themen:['Existentialismus','Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z51',zitat:'Wir wissen nicht, wir können nur raten.',autor:'popper',name:'Karl Popper',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik','Entscheidungen treffen']},{id:'z52',zitat:'Das Problem mit der Welt ist, dass die Dummen sich sicher sind und die Klugen voller Zweifel.',autor:'russell',name:'Bertrand Russell',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z53',zitat:'Es ist besser, gefürchtet zu werden als geliebt, wenn man nicht beides haben kann.',autor:'machiavelli',name:'Niccolò Machiavelli',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z54',zitat:'Unser Herz ist ruhelos, bis es Ruhe findet in dir.',autor:'augustinus',name:'Augustinus',themen:['Metaphysik','Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z55',zitat:'Fortuna dreht ihr Rad, und ich freue mich, es sich drehen zu lassen.',autor:'boethius',name:'Boethius',themen:['Metaphysik','Ethik'],situationen:['Veränderung & Neuanfang','Scheitern & Rückschläge']},{id:'z56',zitat:'Der Mensch wird nicht gut geboren; Güte ist das Ergebnis bewusster Anstrengung.',autor:'xunzi',name:'Xunzi',themen:['Konfuzianismus'],situationen:['Entscheidungen treffen','Selbstzweifel & Kritik']},{id:'z57',zitat:'Das Studium des Buddha-Weges ist das Studium des Selbst.',autor:'dogen',name:'Dogen',themen:['Buddhismus'],situationen:['Sinnsuche & Zweifel']},{id:'z58',zitat:'Yoga ist das Zur-Ruhe-Kommen der Bewegungen des Geistes.',autor:'patanjali',name:'Patanjali',themen:['Vedanta'],situationen:['Stress & Überforderung']},{id:'z59',zitat:'Es gibt kein Außerhalb-des-Textes.',autor:'derrida',name:'Jacques Derrida',themen:['Sprachphilosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z60',zitat:'Wenn wir Leid verhindern können, ohne etwas von vergleichbarer moralischer Bedeutung zu opfern, sollten wir es tun.',autor:'singer',name:'Peter Singer',themen:['Utilitarismus','Ethik'],situationen:['Wut & Ungerechtigkeit','Entscheidungen treffen']},{id:'z61',zitat:'Sapiens dominieren die Welt, weil sie als Einzige in großer Zahl um gemeinsame Mythen herum kooperieren können.',autor:'harari',name:'Yuval Noah Harari',themen:['Transhumanismus','Politische Philosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z62',zitat:'Wäge nicht ab, wie viel du besitzt, sondern wie viel du entbehren kannst.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z63',zitat:'Wir leben, nach Leibniz, in der besten aller möglichen Welten – nicht weil sie perfekt ist, sondern weil jede Alternative noch mehr Übel enthielte.',autor:'leibniz',name:'Gottfried Wilhelm Leibniz',themen:['Rationalismus','Metaphysik'],situationen:['Trauer & Verlust','Sinnsuche & Zweifel']},{id:'z64',zitat:'Was ist schwer? Sich selbst zu erkennen. Was ist leicht? Anderen Ratschläge zu geben.',autor:'thales',name:'Thales von Milet',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z65',zitat:'Alles ist Zahl.',autor:'pythagoras',name:'Pythagoras',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z66',zitat:'Das Sein ist, das Nichtsein ist nicht.',autor:'parmenides',name:'Parmenides',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z67',zitat:'Nichts existiert; und selbst wenn etwas existierte, wäre es nicht erkennbar; und selbst wenn es erkennbar wäre, wäre es nicht mitteilbar.',autor:'gorgias',name:'Gorgias',themen:['Sophistik'],situationen:['Sinnsuche & Zweifel']},{id:'z68',zitat:'Ich versuche, das Göttliche in mir zum Göttlichen im All zurückzuführen.',autor:'plotin',name:'Plotin',themen:['Neuplatonismus'],situationen:['Tod & Vergänglichkeit']},{id:'z69',zitat:'Ich glaube, damit ich verstehe.',autor:'anselm',name:'Anselm von Canterbury',themen:['Scholastik'],situationen:['Sinnsuche & Zweifel']},{id:'z70',zitat:'Die Gnade hebt die Natur nicht auf, sondern vervollkommnet sie.',autor:'aquin',name:'Thomas von Aquin',themen:['Scholastik'],situationen:['Veränderung & Neuanfang']},{id:'z71',zitat:'Lehre deine Zunge, „Ich weiß es nicht" zu sagen, und du wirst Fortschritte machen.',autor:'maimonides',name:'Maimonides',themen:['Islamische Philosophie'],situationen:['Selbstzweifel & Kritik']},{id:'z72',zitat:'Es gibt keine größere Tyrannei als die, die unter dem Schutz der Gesetze und im Namen der Gerechtigkeit ausgeübt wird.',autor:'montesquieu',name:'Montesquieu',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z73',zitat:'Es ist nicht das Wohlwollen des Metzgers, des Brauers oder des Bäckers, von dem wir unser Mittagessen erwarten, sondern von ihrer Rücksicht auf ihr eigenes Interesse.',autor:'adamsmith',name:'Adam Smith',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z74',zitat:'Lebe für andere.',autor:'comte',name:'Auguste Comte',themen:['Positivismus'],situationen:['Liebe & Beziehungen']},{id:'z75',zitat:'Das Universum ist eine Maschine zur Erzeugung von Göttern.',autor:'bergson',name:'Henri Bergson',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z76',zitat:'Ein ungeprüftes Leben ist nicht lebenswert.',autor:'sokrates',name:'Sokrates',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z77',zitat:'Alle Menschen streben von Natur aus nach Wissen.',autor:'aristoteles',name:'Aristoteles',themen:['Erkenntnistheorie'],situationen:['Sinnsuche & Zweifel']},{id:'z78',zitat:'Die Musik ist die stärkste Form der Erziehung, weil Rhythmus und Harmonie am tiefsten in die Seele eindringen.',autor:'platon',name:'Platon',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z79',zitat:'Es genügt nicht, einen guten Geist zu haben; die Hauptsache ist, ihn gut anzuwenden.',autor:'descartes',name:'René Descartes',themen:['Rationalismus'],situationen:['Entscheidungen treffen']},{id:'z80',zitat:'Habe Mut, dich deines eigenen Verstandes zu bedienen!',autor:'kant',name:'Immanuel Kant',themen:['Erkenntnistheorie'],situationen:['Entscheidungen treffen','Selbstzweifel & Kritik']},{id:'z81',zitat:'Wer ein Warum zum Leben hat, erträgt fast jedes Wie.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Scheitern & Rückschläge','Sinnsuche & Zweifel']},{id:'z82',zitat:'Man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Veränderung & Neuanfang']},{id:'z83',zitat:'Religion ist das Opium des Volkes.',autor:'marx',name:'Karl Marx',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z84',zitat:'Nicht das, was wir haben, sondern das, was wir genießen, macht Überfluss aus.',autor:'epikur',name:'Epikur',themen:['Ethik'],situationen:['Stress & Überforderung']},{id:'z85',zitat:'Wir leiden mehr in der Vorstellung als in der Wirklichkeit.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Angst & Unsicherheit']},{id:'z86',zitat:'Sehr wenig ist nötig, um ein glückliches Leben zu führen; es liegt alles in dir selbst, in deiner Art zu denken.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z87',zitat:'Sage dir zuerst, was du sein willst; und tue dann, was du tun musst.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Entscheidungen treffen']},{id:'z88',zitat:'Geh mir aus der Sonne.',autor:'diogenes',name:'Diogenes von Sinope',themen:['Ethik'],situationen:['Wut & Ungerechtigkeit','Selbstzweifel & Kritik']},{id:'z89',zitat:'Der edle Mensch sucht in sich selbst; der gemeine Mensch sucht in anderen.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Selbstzweifel & Kritik']},{id:'z90',zitat:'Wer andere kennt, ist klug; wer sich selbst kennt, ist erleuchtet.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Sinnsuche & Zweifel']},{id:'z91',zitat:'Der Fisch ist im Wasser glücklich, weil er nicht weiß, dass er im Wasser ist.',autor:'zhuangzi',name:'Zhuangzi',themen:['Daoismus'],situationen:['Sinnsuche & Zweifel']},{id:'z92',zitat:'Hass hört niemals durch Hass auf, sondern nur durch Liebe; dies ist ein ewiges Gesetz.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z93',zitat:'Ein weiser Mensch passt seinen Glauben stets der vorliegenden Evidenz an.',autor:'hume',name:'David Hume',themen:['Empirismus'],situationen:['Entscheidungen treffen']},{id:'z94',zitat:'Freiheit besteht darin, dass jeder Mensch innerhalb der Grenzen des Gesetzes über seine Person und seinen Besitz nach eigenem Willen verfügen kann.',autor:'locke',name:'John Locke',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z95',zitat:'Die Wurzel allen Übels liegt darin, dass jemand ein Stück Land einzäunte und sagte: Dies ist mein.',autor:'rousseau',name:'Jean-Jacques Rousseau',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z96',zitat:'Das Gebet ist das Bekenntnis unserer Schwäche.',autor:'voltaire',name:'Voltaire',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z97',zitat:'Das Leben des Menschen im Naturzustand ist einsam, armselig, ekelhaft, tierisch und kurz.',autor:'hobbes',name:'Thomas Hobbes',themen:['Politische Philosophie'],situationen:['Angst & Unsicherheit']},{id:'z98',zitat:'Der freie Mensch denkt an nichts weniger als an den Tod; seine Weisheit besteht in der Betrachtung nicht des Todes, sondern des Lebens.',autor:'spinoza',name:'Baruch de Spinoza',themen:['Rationalismus'],situationen:['Tod & Vergänglichkeit']},{id:'z99',zitat:'Der Mensch ist nur ein Rohr, das schwächste in der Natur; aber er ist ein denkendes Rohr.',autor:'pascal',name:'Blaise Pascal',themen:['Ethik'],situationen:['Selbstzweifel & Kritik']},{id:'z100',zitat:'Ein wenig Philosophie neigt den Geist zum Atheismus, tiefere Philosophie aber führt ihn zur Religion zurück.',autor:'bacon',name:'Francis Bacon',themen:['Erkenntnistheorie'],situationen:['Sinnsuche & Zweifel']},{id:'z101',zitat:'Wer Gegenwart und Vergangenheit vergleicht, erkennt schnell, dass es zu allen Zeiten dieselben menschlichen Wünsche und Leidenschaften gab.',autor:'machiavelli',name:'Niccolò Machiavelli',themen:['Politische Philosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z102',zitat:'Was vernünftig ist, das ist wirklich; und was wirklich ist, das ist vernünftig.',autor:'hegel',name:'G.W.F. Hegel',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z103',zitat:'Es ist besser, ein unzufriedener Mensch zu sein als ein zufriedenes Schwein; besser ein unzufriedener Sokrates als ein zufriedener Narr.',autor:'mill',name:'John Stuart Mill',themen:['Utilitarismus'],situationen:['Selbstzweifel & Kritik']},{id:'z104',zitat:'Talent trifft ein Ziel, das kein anderer treffen kann; Genie trifft ein Ziel, das kein anderer überhaupt sehen kann.',autor:'schopenhauer',name:'Arthur Schopenhauer',themen:['Metaphysik'],situationen:['Selbstzweifel & Kritik']},{id:'z105',zitat:'Der Mensch ist eine Synthese von Unendlichkeit und Endlichkeit.',autor:'kierkegaard',name:'Søren Kierkegaard',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z106',zitat:'Die Grenzen meiner Sprache bedeuten die Grenzen meiner Welt.',autor:'wittgenstein',name:'Ludwig Wittgenstein',themen:['Sprachphilosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z107',zitat:'Wissen dient nicht dazu, zu verstehen; es dient dazu, zu unterscheiden.',autor:'foucault',name:'Michel Foucault',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z108',zitat:'Das Wunder, das die menschlichen Angelegenheiten vor ihrem gewöhnlichen Ruin rettet, ist letztlich die Tatsache der Natalität.',autor:'arendt',name:'Hannah Arendt',themen:['Politische Philosophie'],situationen:['Veränderung & Neuanfang']},{id:'z109',zitat:'Es gibt keine Rechtfertigung für die eigene Gegenwart außer ihrer Ausdehnung in eine unbegrenzte Zukunft.',autor:'beauvoir',name:'Simone de Beauvoir',themen:['Existentialismus'],situationen:['Veränderung & Neuanfang']},{id:'z110',zitat:'Freiheit ist das, was du aus dem machst, was aus dir gemacht wurde.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Entscheidungen treffen']},{id:'z111',zitat:'Nur noch ein Gott kann uns retten.',autor:'heidegger',name:'Martin Heidegger',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z112',zitat:'Drei Leidenschaften, einfach doch überwältigend stark, haben mein Leben regiert: die Sehnsucht nach Liebe, das Streben nach Erkenntnis und unerträgliches Mitleid für das Leiden der Menschheit.',autor:'russell',name:'Bertrand Russell',themen:['Erkenntnistheorie'],situationen:['Liebe & Beziehungen','Sinnsuche & Zweifel']},{id:'z113',zitat:'Wer nicht bereit ist, seine liebsten Ideen der Kritik auszusetzen, hat den Boden der Wissenschaft bereits verlassen.',autor:'popper',name:'Karl Popper',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z114',zitat:'Wir sollten den Kreis unserer moralischen Rücksichtnahme immer weiter ausdehnen.',autor:'singer',name:'Peter Singer',themen:['Utilitarismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z115',zitat:'Die Sterblichen bilden sich ein, dass die Götter geboren werden und Stimme, Gestalt und Kleidung haben wie sie selbst.',autor:'xenophanes',name:'Xenophanes',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z116',zitat:'Alle Dinge waren zusammen, unendlich an Zahl und unendlich klein; dann kam der Nous und brachte Ordnung.',autor:'anaxagoras',name:'Anaxagoras',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z117',zitat:'Durch Liebe werden alle Dinge eins, durch Streit fallen sie wieder auseinander.',autor:'empedokles',name:'Empedokles',themen:['Metaphysik'],situationen:['Veränderung & Neuanfang']},{id:'z118',zitat:'Nicht zu wissen, was vor deiner Geburt geschah, heißt, immer ein Kind zu bleiben.',autor:'cicero',name:'Marcus Tullius Cicero',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z119',zitat:'Gott ist mir näher, als ich mir selbst nahe bin.',autor:'eckhart',name:'Meister Eckhart',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel','Einsamkeit']},{id:'z120',zitat:'Je mehr der Mensch weiß, dass er nicht weiß, desto gelehrter ist er.',autor:'cusanus',name:'Nikolaus von Kues (Cusanus)',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik']},{id:'z121',zitat:'Es gibt unzählige Sonnen und unzählige Erden, die um diese Sonnen kreisen, so wie unsere sieben Planeten um unsere Sonne kreisen.',autor:'bruno',name:'Giordano Bruno',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z122',zitat:'Solange Frauen nicht dieselbe Bildung wie Männer erhalten, wird man ihnen weiterhin vorwerfen, was man ihnen selbst vorenthalten hat.',autor:'wollstonecraft',name:'Mary Wollstonecraft',themen:['Feminismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z123',zitat:'Der Mensch schafft Gott nach seinem eigenen Bilde.',autor:'feuerbach',name:'Ludwig Feuerbach',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z124',zitat:'Die Zukunft gleicht einem stählernen Gehäuse, in dem die Menschen gefangen sein werden, bis das letzte Quäntchen fossiler Brennstoffe verbrannt ist.',autor:'weber',name:'Max Weber',themen:['Soziologie'],situationen:['Angst & Unsicherheit']},{id:'z125',zitat:'Zu wissen und nicht zu handeln, heißt in Wahrheit, noch nicht zu wissen.',autor:'wangyangming',name:'Wang Yangming',themen:['Neukonfuzianismus'],situationen:['Entscheidungen treffen']},{id:'z126',zitat:'Die Gruppensolidarität ist es, die Dynastien errichtet und wieder zu Fall bringt.',autor:'ibnkhaldun',name:'Ibn Khaldun',themen:['Soziologie','Politische Philosophie'],situationen:['Veränderung & Neuanfang']},{id:'z127',zitat:'Komm, komm, wer auch immer du bist. Auch wenn du hundertmal deine Gelübde gebrochen hast, komm dennoch.',autor:'rumi',name:'Rumi',themen:['Sufismus'],situationen:['Trauer & Verlust','Veränderung & Neuanfang']},{id:'z128',zitat:'Müdigkeit ist heute keine Strafe von außen mehr, sondern die Folge eines Zwangs zur Selbstoptimierung, den wir uns selbst auferlegen.',autor:'byungchulhan',name:'Byung-Chul Han',themen:['Existentialismus'],situationen:['Stress & Überforderung']},{id:'z129',zitat:'Gerechtigkeit fragt nicht nur, wie viel jemand besitzt, sondern was jemand tatsächlich zu tun und zu sein imstande ist.',autor:'nussbaum',name:'Martha Nussbaum',themen:['Ethik','Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z130',zitat:'Ich bin, weil wir sind.',autor:'mbiti',name:'John Mbiti',themen:['Afrikanische Philosophie'],situationen:['Einsamkeit','Liebe & Beziehungen']},{id:'z131',zitat:'Der afrikanische Weise muss dekolonisieren, nicht indem er den Westen verwirft, sondern indem er kritisch und auf Augenhöhe mit ihm denkt.',autor:'wiredu',name:'Kwasi Wiredu',themen:['Afrikanische Philosophie'],situationen:['Selbstzweifel & Kritik']},{id:'z132',zitat:'Wir müssen lernen, mit den Unterschieden zu leben, die uns wirklich unterscheiden, und mit der Gemeinsamkeit, die uns trotzdem verbindet.',autor:'appiah',name:'Kwame Anthony Appiah',themen:['Afrikanische Philosophie','Ethik'],situationen:['Wut & Ungerechtigkeit','Liebe & Beziehungen']},{id:'z133',zitat:'Souveränität bedeutet in weiten Teilen der Welt vor allem die Macht zu entscheiden, wer leben und wer sterben darf.',autor:'mbembe',name:'Achille Mbembe',themen:['Afrikanische Philosophie','Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z134',zitat:'Philosophie muss von der Wirklichkeit der Armen und Ausgeschlossenen ausgehen, nicht von einem angeblich neutralen Standpunkt aus.',autor:'dussel',name:'Enrique Dussel',themen:['Befreiungsphilosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z135',zitat:'Lateinamerika muss aufhören, seine eigene Geschichte als bloße Abweichung von der europäischen zu betrachten.',autor:'zea',name:'Leopoldo Zea',themen:['Befreiungsphilosophie'],situationen:['Selbstzweifel & Kritik','Veränderung & Neuanfang']},{id:'z136',zitat:'Niemand befreit einen anderen, niemand befreit sich allein; die Menschen befreien sich gemeinsam, vermittelt durch die Welt.',autor:'freire',name:'Paulo Freire',themen:['Kritische Pädagogik','Befreiungsphilosophie'],situationen:['Veränderung & Neuanfang','Wut & Ungerechtigkeit']},{id:'z137',zitat:'Am Morgen, wenn du nur ungern erwachst, halte dir vor Augen: Ich erwache, um die Arbeit eines Menschen zu verrichten.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z138',zitat:'Verschwende keine Zeit mehr mit Diskussionen darüber, was ein guter Mensch sein sollte. Sei einer.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus','Ethik'],situationen:['Entscheidungen treffen']},{id:'z139',zitat:'Die Zeit des menschlichen Lebens ist nur ein Punkt, ihre Substanz ein ewiges Fließen.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus','Metaphysik'],situationen:['Tod & Vergänglichkeit']},{id:'z140',zitat:'Überall dort, wo man leben kann, kann man auch gut leben.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Veränderung & Neuanfang']},{id:'z141',zitat:'Handle nicht so, als hättest du noch zehntausend Jahre zu leben. Der Tod steht dir bevor: Solange du lebst, solange es noch möglich ist, werde gut.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Sinnsuche & Zweifel','Tod & Vergänglichkeit']},{id:'z142',zitat:'Wir sterben nicht plötzlich, sondern Tag für Tag ein wenig.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Tod & Vergänglichkeit']},{id:'z143',zitat:'Nicht weil die Dinge schwierig sind, wagen wir sie nicht; weil wir sie nicht wagen, sind sie schwierig.',autor:'seneca',name:'Seneca',themen:['Stoizismus','Ethik'],situationen:['Scheitern & Rückschläge','Entscheidungen treffen']},{id:'z144',zitat:'Der Mensch ist dem Menschen heilig.',autor:'seneca',name:'Seneca',themen:['Stoizismus','Ethik'],situationen:['Liebe & Beziehungen','Wut & Ungerechtigkeit']},{id:'z145',zitat:'Nichts gehört uns weniger als die Zeit, deren Herren wir zu sein scheinen.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z146',zitat:'Ein großer Teil des Lebens vergeht damit, Fehler zu machen, ein noch größerer damit, nichts zu tun, und das ganze übrige Leben damit, nicht das zu tun, was wir eigentlich sollten.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Stress & Überforderung','Sinnsuche & Zweifel']},{id:'z147',zitat:'Führe mich, Zeus, und du, Schicksal, wohin auch immer ihr mich zu gehen bestimmt habt; ich werde ohne Zögern folgen.',autor:'kleanthes',name:'Kleanthes',themen:['Stoizismus'],situationen:['Veränderung & Neuanfang','Angst & Unsicherheit']},{id:'z148',zitat:'Wenn Philosophie nichts anderes ist als das Streben nach dem, was edel und gut ist, warum sollte sie dann nicht ebenso für Frauen wie für Männer gelten?',autor:'musonius',name:'Musonius Rufus',themen:['Stoizismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z149',zitat:'Es ist nicht möglich, gut zu leben, ohne zugleich zu philosophieren.',autor:'musonius',name:'Musonius Rufus',themen:['Stoizismus'],situationen:['Sinnsuche & Zweifel']},{id:'z150',zitat:'In Demokratien kann die Mehrheit eine ebenso große Tyrannei ausüben wie irgendein Monarch.',autor:'tocqueville',name:'Alexis de Tocqueville',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z151',zitat:'Der eigentümlich zwanglose Zwang des besseren Arguments.',autor:'habermas',name:'Jürgen Habermas',themen:['Politische Philosophie','Ethik'],situationen:['Entscheidungen treffen']},{id:'z152',zitat:'Freiheit für die Wölfe hat oft den Tod für die Schafe bedeutet.',autor:'berlin',name:'Isaiah Berlin',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z153',zitat:'Pessimismus des Verstandes, Optimismus des Willens.',autor:'gramsci',name:'Antonio Gramsci',themen:['Politische Philosophie'],situationen:['Scheitern & Rückschläge','Veränderung & Neuanfang']},{id:'z154',zitat:'Diese sind die Zeiten, die Menschenseelen auf die Probe stellen.',autor:'paine',name:'Thomas Paine',themen:['Politische Philosophie'],situationen:['Scheitern & Rückschläge','Veränderung & Neuanfang']},{id:'z155',zitat:'Die Gesellschaft ist ein Vertrag zwischen denen, die leben, denen, die tot sind, und denen, die noch geboren werden sollen.',autor:'burke',name:'Edmund Burke',themen:['Politische Philosophie','Konservatismus'],situationen:['Sinnsuche & Zweifel']},{id:'z156',zitat:'Souverän ist, wer über den Ausnahmezustand entscheidet.',autor:'schmitt',name:'Carl Schmitt',themen:['Politische Philosophie'],situationen:['Angst & Unsicherheit']},{id:'z157',zitat:'Kenne deinen Feind und kenne dich selbst, und du wirst in hundert Schlachten niemals in Gefahr geraten.',autor:'sunzi',name:'Sunzi (Sun Tzu)',themen:['Kriegsphilosophie'],situationen:['Entscheidungen treffen','Selbstzweifel & Kritik']},{id:'z158',zitat:'Der höchste Gipfel der Kriegskunst besteht darin, den Feind zu bezwingen, ohne zu kämpfen.',autor:'sunzi',name:'Sunzi (Sun Tzu)',themen:['Kriegsphilosophie'],situationen:['Entscheidungen treffen']},{id:'z159',zitat:'Der Weg des Kriegers ist die entschlossene Annahme des Todes.',autor:'musashi',name:'Miyamoto Musashi',themen:['Kriegsphilosophie'],situationen:['Angst & Unsicherheit','Tod & Vergänglichkeit']},{id:'z160',zitat:'Übe tausend Tage, um eine Fähigkeit zu formen, zehntausend Tage, um sie zu meistern.',autor:'musashi',name:'Miyamoto Musashi',themen:['Kriegsphilosophie'],situationen:['Scheitern & Rückschläge','Stress & Überforderung']},{id:'z161',zitat:'Chanoyu ist nichts weiter, als Wasser zu erhitzen, Tee zuzubereiten und ihn zu trinken.',autor:'rikyu',name:'Sen no Rikyū',themen:['Buddhismus','Ethik'],situationen:['Sinnsuche & Zweifel','Stress & Überforderung']},{id:'z162',zitat:'Harmonie ist zu schätzen, und Widerspruch um seiner selbst willen ist zu vermeiden.',autor:'shotoku',name:'Prinz Shōtoku',themen:['Politische Philosophie'],situationen:['Liebe & Beziehungen','Wut & Ungerechtigkeit']},{id:'z163',zitat:'Selbst ein guter Mensch wird im Reinen Land wiedergeboren – wie viel mehr ein böser Mensch.',autor:'shinran',name:'Shinran',themen:['Buddhismus'],situationen:['Selbstzweifel & Kritik','Trauer & Verlust']},{id:'z164',zitat:'Was verborgen bleibt, ist die Blüte.',autor:'zeami',name:'Zeami Motokiyo',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z165',zitat:'Der Weg des Samurai ist im Sterben zu finden.',autor:'tsunetomo',name:'Yamamoto Tsunetomo',themen:['Kriegsphilosophie'],situationen:['Angst & Unsicherheit','Tod & Vergänglichkeit']},{id:'z166',zitat:'Que sais-je? – Was weiß ich?',autor:'montaigne',name:'Michel de Montaigne',themen:['Erkenntnistheorie'],situationen:['Selbstzweifel & Kritik','Sinnsuche & Zweifel']},{id:'z167',zitat:'Der größte Fund meiner Generation ist, dass Menschen ihr Leben verändern können, indem sie ihre Geisteshaltung verändern.',autor:'james',name:'William James',themen:['Erkenntnistheorie'],situationen:['Veränderung & Neuanfang']},{id:'z168',zitat:'Der Mensch ist mehr, als er von sich wissen kann.',autor:'jaspers',name:'Karl Jaspers',themen:['Existentialismus'],situationen:['Selbstzweifel & Kritik','Sinnsuche & Zweifel']},{id:'z169',zitat:'Das Antlitz sagt mir: Du sollst nicht töten.',autor:'levinas',name:'Emmanuel Levinas',themen:['Ethik'],situationen:['Wut & Ungerechtigkeit']},{id:'z170',zitat:'Aufmerksamkeit ist die seltenste und reinste Form der Großzügigkeit.',autor:'weil',name:'Simone Weil',themen:['Ethik'],situationen:['Liebe & Beziehungen','Einsamkeit']},{id:'z171',zitat:'Liebe ist eine Handlung, nicht bloß ein Gefühl.',autor:'hooks',name:'bell hooks',themen:['Feminismus','Ethik'],situationen:['Liebe & Beziehungen']},{id:'z172',zitat:'Du bist ein Loch im Universum, durch das das Universum sich selbst betrachtet.',autor:'watts',name:'Alan Watts',themen:['Buddhismus'],situationen:['Sinnsuche & Zweifel','Einsamkeit']},{id:'z173',zitat:'Der Anfang ist der wichtigste Teil der Arbeit.',autor:'platon',name:'Platon',themen:['Ethik'],situationen:['Veränderung & Neuanfang','Entscheidungen treffen']},{id:'z174',zitat:'Bildung ist der beste Proviant für das Alter.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z175',zitat:'Der gesunde Menschenverstand ist die am gerechtesten verteilte Sache der Welt.',autor:'descartes',name:'René Descartes',themen:['Rationalismus'],situationen:['Selbstzweifel & Kritik']},{id:'z176',zitat:'Wo Macht ist, ist Widerstand; und dennoch oder gerade deshalb ist dieser Widerstand niemals außerhalb der Macht.',autor:'foucault',name:'Michel Foucault',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z177',zitat:'Es gibt keine Tatsachen, nur Interpretationen.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel','Selbstzweifel & Kritik']},{id:'z178',zitat:'Zwei Dinge erfüllen das Gemüt mit immer neuer und zunehmender Bewunderung und Ehrfurcht: der bestirnte Himmel über mir und das moralische Gesetz in mir.',autor:'kant',name:'Immanuel Kant',themen:['Ethik','Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z179',zitat:'Die Welt ist meine Vorstellung.',autor:'schopenhauer',name:'Arthur Schopenhauer',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z180',zitat:'Nichts Großes in der Welt ist ohne Leidenschaft vollbracht worden.',autor:'hegel',name:'G.W.F. Hegel',themen:['Metaphysik'],situationen:['Veränderung & Neuanfang','Entscheidungen treffen']},{id:'z181',zitat:'Ich zitiere andere nur, um mich selbst besser auszudrücken.',autor:'montaigne',name:'Michel de Montaigne',themen:['Erkenntnistheorie'],situationen:['Sinnsuche & Zweifel']},{id:'z182',zitat:'Wir sind allein, ohne Entschuldigungen.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Entscheidungen treffen','Angst & Unsicherheit']},{id:'z183',zitat:'Alles Erhabene ist so schwer wie selten.',autor:'spinoza',name:'Baruch de Spinoza',themen:['Rationalismus'],situationen:['Scheitern & Rückschläge','Sinnsuche & Zweifel']},{id:'z184',zitat:'Ein Organismus hat genau dann Bewusstsein, wenn es etwas gibt, das es bedeutet, dieser Organismus zu sein.',autor:'nagel',name:'Thomas Nagel',themen:['Philosophie des Geistes'],situationen:['Sinnsuche & Zweifel']},{id:'z185',zitat:'Warum begleitet subjektives Erleben überhaupt physische Prozesse? Das ist das schwierige Problem des Bewusstseins.',autor:'chalmers',name:'David Chalmers',themen:['Philosophie des Geistes'],situationen:['Sinnsuche & Zweifel','Selbstzweifel & Kritik']},{id:'z186',zitat:'Syntax allein ist niemals hinreichend für Semantik.',autor:'searle',name:'John Searle',themen:['Philosophie des Geistes','Sprachphilosophie'],situationen:['Selbstzweifel & Kritik']},{id:'z187',zitat:'Wenn die Menschen einander wie sich selbst lieben würden, gäbe es keine Diebe mehr.',autor:'mozi',name:'Mozi',themen:['Mohismus'],situationen:['Liebe & Beziehungen','Wut & Ungerechtigkeit']},{id:'z188',zitat:'Gerechtigkeit ist unausweichlich urteilend.',autor:'sandel',name:'Michael Sandel',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen','Wut & Ungerechtigkeit']},{id:'z189',zitat:'Wenn Paradigmen sich ändern, verändert sich mit ihnen auch die Welt selbst, in der Wissenschaftler arbeiten.',autor:'kuhn',name:'Thomas Kuhn',themen:['Erkenntnistheorie'],situationen:['Veränderung & Neuanfang']},{id:'z190',zitat:'Woraus die Dinge entstehen, dahin vergehen sie auch wieder nach Notwendigkeit; denn sie zahlen einander Buße und Strafe für ihre Ungerechtigkeit, gemäß der Ordnung der Zeit.',autor:'anaximander',name:'Anaximander',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z191',zitat:'Nichts geschieht durch Zufall, sondern alles aus einem Grund und aus Notwendigkeit.',autor:'leukipp',name:'Leukipp',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z192',zitat:'Das Ziel des Lebens ist es, im Einklang mit der Natur zu leben.',autor:'zenonkition',name:'Zenon von Kition',themen:['Stoizismus'],situationen:['Sinnsuche & Zweifel']},{id:'z193',zitat:'Entitäten sollen nicht ohne Notwendigkeit vervielfacht werden.',autor:'ockham',name:'Wilhelm von Ockham',themen:['Scholastik'],situationen:['Entscheidungen treffen']},{id:'z194',zitat:'Nichts entsteht aus sich selbst, aus einem anderen, aus beidem oder ohne Ursache.',autor:'nagarjuna',name:'Nagarjuna',themen:['Buddhismus'],situationen:['Sinnsuche & Zweifel']},{id:'z195',zitat:'Brahman ist wirklich, die Welt ist Illusion, und die individuelle Seele ist nichts anderes als Brahman selbst.',autor:'shankara',name:'Shankara',themen:['Vedanta'],situationen:['Sinnsuche & Zweifel']},{id:'z196',zitat:'Der erleuchtete Herrscher kontrolliert seine Minister allein durch zwei Hebel: Belohnung und Bestrafung.',autor:'hanfei',name:'Han Feizi',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z197',zitat:'Frei sein ist nichts – frei werden ist der Himmel.',autor:'fichte',name:'Johann Gottlieb Fichte',themen:['Metaphysik'],situationen:['Veränderung & Neuanfang']},{id:'z198',zitat:'Natur soll sichtbarer Geist, Geist soll unsichtbare Natur sein.',autor:'schelling',name:'F.W.J. Schelling',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel']},{id:'z199',zitat:'Der Leib ist unser allgemeines Medium, überhaupt eine Welt zu haben.',autor:'merleauponty',name:'Maurice Merleau-Ponty',themen:['Phänomenologie'],situationen:['Sinnsuche & Zweifel']},{id:'z200',zitat:'Gerechtigkeit ist die erste Tugend gesellschaftlicher Institutionen, so wie Wahrheit die erste Tugend von Gedankensystemen ist.',autor:'rawls',name:'John Rawls',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z201',zitat:'Geschlecht ist immer ein Tun, nie ein fertiges Sein.',autor:'butler',name:'Judith Butler',themen:['Feminismus'],situationen:['Selbstzweifel & Kritik']},{id:'z202',zitat:'Maschinenintelligenz ist die letzte Erfindung, die die Menschheit je machen muss.',autor:'bostrom',name:'Nick Bostrom',themen:['Transhumanismus'],situationen:['Angst & Unsicherheit','Veränderung & Neuanfang']},{id:'z203',zitat:'Was soll man also mit Menschen machen, die die Anerkennung von jenen suchen oder meiden, die nicht wissen, wo und wer sie selbst sind?',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Selbstzweifel & Kritik','Liebe & Beziehungen']},{id:'z204',zitat:'Alles, was wir hören, ist eine Meinung, keine Tatsache. Alles, was wir sehen, ist eine Perspektive, nicht die Wahrheit.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus','Erkenntnistheorie'],situationen:['Wut & Ungerechtigkeit','Selbstzweifel & Kritik']},{id:'z205',zitat:'Der Mensch ist von Natur aus ein politisches Wesen.',autor:'aristoteles',name:'Aristoteles',themen:['Politische Philosophie'],situationen:['Einsamkeit','Liebe & Beziehungen']},{id:'z206',zitat:'Man handelt nur nach derjenigen Maxime, durch die man zugleich wollen kann, dass sie ein allgemeines Gesetz werde.',autor:'kant',name:'Immanuel Kant',themen:['Ethik'],situationen:['Entscheidungen treffen']},{id:'z207',zitat:'Talent trifft ein Ziel, das keiner sonst treffen kann; Genie trifft ein Ziel, das keiner sonst sehen kann.',autor:'schopenhauer',name:'Arthur Schopenhauer',themen:['Ethik'],situationen:['Selbstzweifel & Kritik']},{id:'z208',zitat:'Im Herzen des Winters lernte ich endlich, dass in mir ein unbesiegbarer Sommer lag.',autor:'camus',name:'Albert Camus',themen:['Existentialismus'],situationen:['Scheitern & Rückschläge','Trauer & Verlust']},{id:'z209',zitat:'Nicht das, was wir haben, sondern das, was wir genießen, macht uns reich.',autor:'epikur',name:'Epikur',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z210',zitat:'Wir leiden mehr in der Einbildung als in der Wirklichkeit.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Angst & Unsicherheit','Stress & Überforderung']},{id:'z211',zitat:'Ein Zimmer ohne Bücher ist wie ein Körper ohne Seele.',autor:'cicero',name:'Cicero',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z212',zitat:'Das ganze Problem der Welt ist, dass Dumme und Fanatiker sich immer so sicher sind, während weisere Menschen voller Zweifel sind.',autor:'russell',name:'Bertrand Russell',themen:['Erkenntnistheorie'],situationen:['Wut & Ungerechtigkeit','Selbstzweifel & Kritik']},{id:'z213',zitat:'Nicht von der Güte des Metzgers, des Brauers oder des Bäckers erwarten wir unser Essen, sondern von deren Rücksicht auf ihr eigenes Interesse.',autor:'adamsmith',name:'Adam Smith',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z215',zitat:'Der edle Mensch verlangt viel von sich selbst; der gewöhnliche Mensch verlangt viel von anderen.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Selbstzweifel & Kritik','Wut & Ungerechtigkeit']},{id:'z218',zitat:'Es ist besser, gefürchtet als geliebt zu werden, wenn man nicht beides zugleich sein kann.',autor:'machiavelli',name:'Niccolò Machiavelli',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z219',zitat:'Die Geschichte lehrt, dass Völker und Regierungen niemals etwas aus der Geschichte gelernt haben.',autor:'hegel',name:'G.W.F. Hegel',themen:['Metaphysik','Politische Philosophie'],situationen:['Wut & Ungerechtigkeit','Sinnsuche & Zweifel']},{id:'z220',zitat:'Wir können leicht einem Kind vergeben, das sich vor der Dunkelheit fürchtet. Die wahre Tragödie des Lebens ist, wenn Menschen sich vor dem Licht fürchten.',autor:'platon',name:'Platon',themen:['Erkenntnistheorie'],situationen:['Angst & Unsicherheit','Selbstzweifel & Kritik']},{id:'z221',zitat:'Sage dir zuerst, was du sein willst, und tue dann, was du zu tun hast.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Entscheidungen treffen','Veränderung & Neuanfang']},{id:'z222',zitat:'Ein Wasserkrug wird tropfenweise gefüllt.',autor:'buddha',name:'Buddha',themen:['Buddhismus'],situationen:['Stress & Überforderung','Scheitern & Rückschläge']},{id:'z223',zitat:'Der Charakter des Menschen ist sein Schicksal.',autor:'heraklit',name:'Heraklit',themen:['Metaphysik'],situationen:['Sinnsuche & Zweifel','Selbstzweifel & Kritik']},{id:'z224',zitat:'Urteile über einen Menschen nach seinen Fragen, nicht nach seinen Antworten.',autor:'voltaire',name:'Voltaire',themen:['Erkenntnistheorie'],situationen:['Sinnsuche & Zweifel']},{id:'z225',zitat:'Religion ist Opium für das Volk.',autor:'marx',name:'Karl Marx',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z226',zitat:'In jedem wahren Mann ist ein Kind versteckt, das spielen will.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z227',zitat:'Ändere dein Leben heute. Wette nicht auf die Zukunft, handle jetzt, ohne Verzögerung.',autor:'beauvoir',name:'Simone de Beauvoir',themen:['Existentialismus','Feminismus'],situationen:['Veränderung & Neuanfang','Entscheidungen treffen']},{id:'z228',zitat:'Die Wunde ist der Ort, wo das Licht in dich eindringt.',autor:'rumi',name:'Rumi',themen:['Sufismus'],situationen:['Trauer & Verlust','Scheitern & Rückschläge']},{id:'z229',zitat:'Verträge ohne das Schwert sind nichts als Worte.',autor:'hobbes',name:'Thomas Hobbes',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z230',zitat:'Über sich selbst, über seinen eigenen Körper und Geist, ist das Individuum souverän.',autor:'mill',name:'John Stuart Mill',themen:['Politische Philosophie','Utilitarismus'],situationen:['Entscheidungen treffen','Wut & Ungerechtigkeit']},{id:'z231',zitat:'Wir haben nicht wenig Zeit, sondern wir verlieren viel davon.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z232',zitat:'Alles, was geschehen kann, kann jederzeit geschehen.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Angst & Unsicherheit']},{id:'z233',zitat:'Die beste Rache ist, nicht so zu sein wie dein Feind.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z234',zitat:'Verschwende nicht den Rest deines Lebens mit Gedanken über andere Menschen.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Einsamkeit','Stress & Überforderung']},{id:'z235',zitat:'Wer mit Ungeheuern kämpft, mag zusehen, dass er nicht dabei selbst zum Ungeheuer wird.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Ethik'],situationen:['Wut & Ungerechtigkeit','Selbstzweifel & Kritik']},{id:'z236',zitat:'Der Mensch ist ein Seil, geknüpft zwischen Tier und Übermensch.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Veränderung & Neuanfang']},{id:'z237',zitat:'Was du nicht willst, das man dir tu, das füg auch keinem andern zu.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Liebe & Beziehungen','Wut & Ungerechtigkeit']},{id:'z238',zitat:'Studieren ohne zu denken ist nutzlos; denken ohne zu studieren ist gefährlich.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Sinnsuche & Zweifel']},{id:'z239',zitat:'Ein guter Reisender hat keine festen Pläne und ist nicht darauf bedacht, anzukommen.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Veränderung & Neuanfang','Sinnsuche & Zweifel']},{id:'z240',zitat:'Wer isoliert lebt, ist entweder ein Tier oder ein Gott.',autor:'aristoteles',name:'Aristoteles',themen:['Politische Philosophie'],situationen:['Einsamkeit']},{id:'z241',zitat:'Der Tod bedeutet uns nichts; denn solange wir sind, ist der Tod nicht da, und wenn der Tod da ist, sind wir nicht mehr.',autor:'epikur',name:'Epikur',themen:['Ethik'],situationen:['Tod & Vergänglichkeit','Angst & Unsicherheit']},{id:'z242',zitat:'Man muss über das Wichtigste im Leben in jungen wie in alten Jahren philosophieren.',autor:'epikur',name:'Epikur',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z243',zitat:'Fische treffen sich im Wasser, Menschen treffen sich im Tao.',autor:'zhuangzi',name:'Zhuangzi',themen:['Daoismus'],situationen:['Liebe & Beziehungen']},{id:'z244',zitat:'Die Philosophie ist ein Kampf gegen die Verhexung unseres Verstandes durch die Mittel unserer Sprache.',autor:'wittgenstein',name:'Ludwig Wittgenstein',themen:['Sprachphilosophie'],situationen:['Sinnsuche & Zweifel']},{id:'z245',zitat:'Das Böse ist niemals „radikal", sondern immer nur extrem.',autor:'arendt',name:'Hannah Arendt',themen:['Politische Philosophie','Ethik'],situationen:['Wut & Ungerechtigkeit']},{id:'z246',zitat:'Du selbst musst dich anstrengen; die Erwachten zeigen nur den Weg.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Veränderung & Neuanfang','Entscheidungen treffen']},{id:'z247',zitat:'Zwei Gefängnisinsassen, deren Zellen aneinandergrenzen, kommunizieren, indem sie an die Wand klopfen.',autor:'weil',name:'Simone Weil',themen:['Ethik'],situationen:['Einsamkeit','Liebe & Beziehungen']},{id:'z248',zitat:'Die Wahl zu lieben ist eine Möglichkeit, sich aktiv der Angst zu widersetzen.',autor:'hooks',name:'bell hooks',themen:['Feminismus','Ethik'],situationen:['Angst & Unsicherheit','Liebe & Beziehungen']},{id:'z249',zitat:'Alle Menschen haben ein Herz, das das Leiden anderer nicht ertragen kann.',autor:'mengzi',name:'Mengzi',themen:['Konfuzianismus'],situationen:['Liebe & Beziehungen','Wut & Ungerechtigkeit']},{id:'z250',zitat:'Die menschliche Natur ist von Geburt an zum Schlechten geneigt; ihre Güte ist anerzogen.',autor:'xunzi',name:'Xunzi',themen:['Konfuzianismus'],situationen:['Selbstzweifel & Kritik']},{id:'z251',zitat:'Du bist nicht nur ein Tropfen im Ozean, sondern der ganze Ozean in einem einzigen Tropfen.',autor:'rumi',name:'Rumi',themen:['Sufismus'],situationen:['Sinnsuche & Zweifel','Einsamkeit']},{id:'z252',zitat:'Ich bin ein Weltbürger.',autor:'diogenes',name:'Diogenes von Sinope',themen:['Ethik'],situationen:['Einsamkeit','Sinnsuche & Zweifel']},{id:'z300',zitat:'Wir trauern nicht so sehr um das, was wir verloren haben, sondern um das, was wir uns von ihm erhofft hatten.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Trauer & Verlust']},{id:'z301',zitat:'Alles, was geschieht, ist so gewöhnlich und bekannt wie die Rose im Frühling und die Frucht im Sommer; so auch Krankheit, Tod, Verleumdung, Intrige und alles, was Toren erfreut oder betrübt.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Trauer & Verlust']},{id:'z302',zitat:'Alles Zusammengesetzte ist vergänglich – wache achtsam über dieses Vergehen.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Trauer & Verlust','Tod & Vergänglichkeit']},{id:'z303',zitat:'Unsere größte Ehre liegt nicht darin, niemals zu fallen, sondern jedes Mal wieder aufzustehen, wenn wir gefallen sind.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Trauer & Verlust','Scheitern & Rückschläge']},{id:'z304',zitat:'Mitten im Winter erfuhr ich schließlich, dass in mir ein unbesiegbarer Sommer steckte.',autor:'camus',name:'Albert Camus',themen:['Existentialismus'],situationen:['Trauer & Verlust']},{id:'z305',zitat:'Die Wunde ist der Ort, an dem das Licht in dich eindringt.',autor:'rumi',name:'Rumi (Dschalal ad-Din)',themen:['Sufismus'],situationen:['Trauer & Verlust']},{id:'z306',zitat:'Die Zeit heilt die Wunden, die die Vernunft allein nicht heilen kann.',autor:'cicero',name:'Marcus Tullius Cicero',themen:['Stoizismus'],situationen:['Trauer & Verlust']},{id:'z307',zitat:'Nicht die Dinge selbst beunruhigen die Menschen, sondern ihre Urteile über die Dinge.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Trauer & Verlust','Angst & Unsicherheit']},{id:'z308',zitat:'Aufmerksamkeit, in ihrer reinsten Form, ist Gebet.',autor:'weil',name:'Simone Weil',themen:['Existentialismus'],situationen:['Trauer & Verlust']},{id:'z309',zitat:'Angst ist der Schwindel der Freiheit.',autor:'kierkegaard',name:'Søren Kierkegaard',themen:['Existentialismus'],situationen:['Angst & Unsicherheit']},{id:'z310',zitat:'Mein Leben war voller Unglücke, von denen die meisten nie eingetreten sind.',autor:'montaigne',name:'Michel de Montaigne',themen:['Skeptizismus'],situationen:['Angst & Unsicherheit']},{id:'z311',zitat:'Wir leiden öfter in der Vorstellung als in der Wirklichkeit.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Angst & Unsicherheit','Stress & Überforderung']},{id:'z312',zitat:'Die Furcht entsteht nicht aus der Vernunft, sondern aus der Unwissenheit.',autor:'spinoza',name:'Baruch de Spinoza',themen:['Rationalismus'],situationen:['Angst & Unsicherheit']},{id:'z313',zitat:'Der Mensch ist zur Freiheit verurteilt.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Angst & Unsicherheit','Entscheidungen treffen']},{id:'z314',zitat:'Wenn du über etwas Äußeres beunruhigt bist, ist es nicht das Ding, das dich stört, sondern dein Urteil darüber – und das kannst du in diesem Moment auslöschen.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Angst & Unsicherheit']},{id:'z315',zitat:'Der einzige Weg, das Leben in vollem Umfang zu erfassen, besteht darin, mit seiner Unsicherheit zu tanzen, statt gegen sie anzukämpfen.',autor:'watts',name:'Alan Watts',themen:['Daoismus'],situationen:['Angst & Unsicherheit']},{id:'z316',zitat:'Die Angst offenbart im Dasein das Sein zum eigensten Seinkönnen.',autor:'heidegger',name:'Martin Heidegger',themen:['Existentialismus'],situationen:['Angst & Unsicherheit']},{id:'z317',zitat:'Es ist nicht der Mensch, der wenig hat, arm, sondern der, der mehr begehrt, als er hat.',autor:'epikur',name:'Epikur',themen:['Stoizismus'],situationen:['Angst & Unsicherheit']},{id:'z318',zitat:'Das Hindernis für die Handlung fördert die Handlung. Was der Handlung im Weg steht, wird zum Weg.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Scheitern & Rückschläge']},{id:'z319',zitat:'Der Weiseste ist, wer weiß, dass er nichts Vollkommenes weiß, und dennoch weiterfragt.',autor:'sokrates',name:'Sokrates',themen:['Erkenntnistheorie'],situationen:['Scheitern & Rückschläge','Selbstzweifel & Kritik']},{id:'z320',zitat:'Kein Baum wird stark und tief verwurzelt, wenn nicht viel Wind an ihm rüttelt.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Scheitern & Rückschläge']},{id:'z321',zitat:'Es sind nicht die Ereignisse, die uns aus der Bahn werfen, sondern wie wir uns dazu verhalten – und das Verhalten liegt immer bei uns.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Scheitern & Rückschläge']},{id:'z322',zitat:'Übe tausendmal, bevor du urteilst, und zehntausendmal, bevor du meisterst.',autor:'musashi',name:'Miyamoto Musashi',themen:['Bushido'],situationen:['Scheitern & Rückschläge']},{id:'z323',zitat:'Es ist keine Schande, zu fallen. Es ist eine Schande, liegen zu bleiben.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Scheitern & Rückschläge']},{id:'z324',zitat:'Wir sind das, was wir wiederholt tun. Vortrefflichkeit ist daher keine Handlung, sondern eine Gewohnheit.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Scheitern & Rückschläge','Entscheidungen treffen']},{id:'z325',zitat:'Man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Scheitern & Rückschläge']},{id:'z326',zitat:'Kluges Handeln setzt voraus, dass man das Richtige zur richtigen Zeit, aus dem richtigen Grund und auf die richtige Weise tut.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Entscheidungen treffen']},{id:'z327',zitat:'Habe Mut, dich deines eigenen Verstandes zu bedienen.',autor:'kant',name:'Immanuel Kant',themen:['Aufklärung'],situationen:['Entscheidungen treffen','Selbstzweifel & Kritik']},{id:'z328',zitat:'Man muss sich Sisyphos als einen glücklichen Menschen vorstellen.',autor:'camus',name:'Albert Camus',themen:['Existentialismus'],situationen:['Entscheidungen treffen','Sinnsuche & Zweifel']},{id:'z329',zitat:'Wer sein Ziel kennt, hat schon die halbe Strecke zurückgelegt.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Entscheidungen treffen']},{id:'z330',zitat:'Der Mensch ist frei geboren, und überall liegt er in Ketten.',autor:'rousseau',name:'Jean-Jacques Rousseau',themen:['Politische Philosophie'],situationen:['Entscheidungen treffen']},{id:'z331',zitat:'Denke nicht unehrlich. Der Weg ist im Training.',autor:'musashi',name:'Miyamoto Musashi',themen:['Bushido'],situationen:['Entscheidungen treffen']},{id:'z332',zitat:'Verschwende nicht den Rest deines Lebens damit, dir Gedanken über andere zu machen, wenn es nicht auf einen gemeinsamen Nutzen bezogen ist.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Entscheidungen treffen']},{id:'z333',zitat:'Der edle Mensch prüft sich täglich, um klar zu sehen und richtig zu handeln.',autor:'xunzi',name:'Xunzi',themen:['Konfuzianismus'],situationen:['Entscheidungen treffen','Selbstzweifel & Kritik']},{id:'z334',zitat:'Die beste Rache ist, nicht so zu werden wie der, der dir Unrecht getan hat.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z335',zitat:'Der Zorn ist ein kurzer Wahnsinn.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z336',zitat:'Sich zu ärgern ist leicht – jeder kann das. Aber sich über die richtige Person, im richtigen Maß, zur richtigen Zeit, aus dem richtigen Grund und auf die richtige Weise zu ärgern, das ist nicht leicht.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Wut & Ungerechtigkeit']},{id:'z337',zitat:'Niemand hat das Recht zu gehorchen.',autor:'arendt',name:'Hannah Arendt',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z338',zitat:'Ungerechtigkeit ist nur so lange tolerierbar, wie sie nötig ist, um eine noch größere Ungerechtigkeit zu vermeiden.',autor:'rawls',name:'John Rawls',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z339',zitat:'Die höchste Ungerechtigkeit entsteht oft aus der wörtlichsten Anwendung des Rechts.',autor:'cicero',name:'Marcus Tullius Cicero',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z340',zitat:'Wer dich beleidigt, beleidigt seine eigene Vorstellung von dir – nicht dich selbst.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Wut & Ungerechtigkeit']},{id:'z341',zitat:'Zorn kann auf Ungerechtigkeit hinweisen, doch nur der Wunsch nach Wiedergutmachung, nicht nach Vergeltung, führt zu echter Gerechtigkeit.',autor:'nussbaum',name:'Martha Nussbaum',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z342',zitat:'Liebe ist der Wunsch der Seele, das Schöne für immer zu besitzen.',autor:'platon',name:'Platon',themen:['Ethik'],situationen:['Liebe & Beziehungen']},{id:'z343',zitat:'Ein Freund ist eine Seele, die in zwei Körpern wohnt.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Liebe & Beziehungen','Einsamkeit']},{id:'z344',zitat:'Wenn man mich drängt zu sagen, warum ich ihn liebte, fühle ich, dass es sich nicht anders ausdrücken lässt, als indem ich antworte: Weil er es war, weil ich es war.',autor:'montaigne',name:'Michel de Montaigne',themen:['Skeptizismus'],situationen:['Liebe & Beziehungen']},{id:'z345',zitat:'Deine Aufgabe ist es nicht, nach Liebe zu suchen, sondern nur, all die Mauern zu finden, die du in dir selbst gegen sie errichtet hast.',autor:'rumi',name:'Rumi (Dschalal ad-Din)',themen:['Sufismus'],situationen:['Liebe & Beziehungen']},{id:'z346',zitat:'In der echten Liebe erkennt man sich gegenseitig als Subjekt an, nicht der eine als Objekt des anderen.',autor:'beauvoir',name:'Simone de Beauvoir',themen:['Existentialismus'],situationen:['Liebe & Beziehungen']},{id:'z347',zitat:'Behandle andere so, wie du selbst behandelt werden möchtest – das ist die Essenz der Menschlichkeit.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Liebe & Beziehungen']},{id:'z348',zitat:'Das Antlitz des Anderen verpflichtet mich, bevor ich überhaupt entscheiden kann, ob ich verpflichtet sein will.',autor:'levinas',name:'Emmanuel Levinas',themen:['Phänomenologie'],situationen:['Liebe & Beziehungen']},{id:'z349',zitat:'Von allem, was Weisheit für ein glückliches Leben verschafft, ist Freundschaft das Größte.',autor:'epikur',name:'Epikur',themen:['Stoizismus'],situationen:['Liebe & Beziehungen','Einsamkeit']},{id:'z350',zitat:'Einsamkeit ist gefährlich, denn sie kann in völlige Verlassenheit umschlagen; Alleinsein dagegen kann zur bedeutendsten Form des menschlichen Daseins werden.',autor:'arendt',name:'Hannah Arendt',themen:['Politische Philosophie'],situationen:['Einsamkeit']},{id:'z351',zitat:'In der Einsamkeit wächst, was einer mitbringt, auch das innere Vieh.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Einsamkeit']},{id:'z352',zitat:'Nur wer allein sein kann, ohne einsam zu sein, hat wahre Freiheit gefunden.',autor:'zhuangzi',name:'Zhuangzi',themen:['Daoismus'],situationen:['Einsamkeit']},{id:'z353',zitat:'Wir müssen uns eine Hinterkammer ganz für uns behalten, in der wir unsere wahre Freiheit und unseren wichtigsten Rückzugsort einrichten.',autor:'montaigne',name:'Michel de Montaigne',themen:['Skeptizismus'],situationen:['Einsamkeit']},{id:'z354',zitat:'In der Gesellschaft der Müdigkeit verbindet uns die ständige Erreichbarkeit, doch sie macht uns zugleich einsamer.',autor:'byungchulhan',name:'Byung-Chul Han',themen:['Kritische Theorie'],situationen:['Einsamkeit','Stress & Überforderung']},{id:'z355',zitat:'Man muss sich selbst zum Freund werden, um nie ganz allein zu sein.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Einsamkeit']},{id:'z356',zitat:'Du bist nicht in das Universum geboren, du bist aus ihm herausgekommen – wie eine Welle aus dem Meer.',autor:'watts',name:'Alan Watts',themen:['Daoismus'],situationen:['Einsamkeit']},{id:'z357',zitat:'Hat man sein Warum des Lebens, so verträgt man sich fast mit jedem Wie.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z358',zitat:'Die Existenz geht der Essenz voraus – der Mensch ist zunächst nichts, er wird erst später etwas, und zwar das, was er aus sich macht.',autor:'sartre',name:'Jean-Paul Sartre',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z359',zitat:'Das Leben kann nur rückwärts verstanden, muss aber vorwärts gelebt werden.',autor:'kierkegaard',name:'Søren Kierkegaard',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z360',zitat:'Es gibt keinen Weg zum Glück – Glücklichsein ist der Weg.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Sinnsuche & Zweifel']},{id:'z361',zitat:'Wer andere kennt, ist klug. Wer sich selbst kennt, ist erleuchtet.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Sinnsuche & Zweifel','Selbstzweifel & Kritik']},{id:'z362',zitat:'Der Mensch wird er selbst nur in der Kommunikation mit anderen Menschen.',autor:'jaspers',name:'Karl Jaspers',themen:['Existentialismus'],situationen:['Sinnsuche & Zweifel']},{id:'z363',zitat:'Ein ungeprüftes Leben ist für den Menschen nicht lebenswert.',autor:'sokrates',name:'Sokrates',themen:['Ethik'],situationen:['Sinnsuche & Zweifel']},{id:'z364',zitat:'Der Sinn des Lebens ist einfach, aber wir wollen ihn hartnäckig kompliziert machen.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Sinnsuche & Zweifel']},{id:'z365',zitat:'Der größte Fund meiner Generation ist, dass Menschen durch die Veränderung ihrer inneren Haltung ihr äußeres Leben verändern können.',autor:'james',name:'William James',themen:['Pragmatismus'],situationen:['Sinnsuche & Zweifel']},{id:'z366',zitat:'Eine Reise von tausend Meilen beginnt mit einem einzigen Schritt.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Veränderung & Neuanfang']},{id:'z367',zitat:'Nichts ist beständig außer dem Wandel selbst.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Veränderung & Neuanfang']},{id:'z368',zitat:'Jeder neue Tag ist eine neue Gelegenheit, das eigene Leben umzugestalten.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Veränderung & Neuanfang']},{id:'z369',zitat:'Fließe wie das Wasser, das jedes Hindernis umspielt, statt sich an ihm zu brechen.',autor:'zhuangzi',name:'Zhuangzi',themen:['Daoismus'],situationen:['Veränderung & Neuanfang']},{id:'z370',zitat:'Die Kraft, die alles wandelt, ist dieselbe, die auch dich formt – widersetze dich ihr nicht.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Veränderung & Neuanfang']},{id:'z371',zitat:'Es ist gleichgültig, wie langsam du gehst, solange du nicht stehen bleibst.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Veränderung & Neuanfang']},{id:'z372',zitat:'Es ist unmöglich, dass jemand beginnt zu lernen, was er zu wissen glaubt, bereits zu können.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Veränderung & Neuanfang']},{id:'z373',zitat:'Der Tod bedeutet uns nichts, denn solange wir sind, ist der Tod nicht da, und wenn der Tod da ist, sind wir nicht mehr.',autor:'epikur',name:'Epikur',themen:['Stoizismus'],situationen:['Tod & Vergänglichkeit']},{id:'z374',zitat:'Philosophieren heißt sterben lernen.',autor:'montaigne',name:'Michel de Montaigne',themen:['Skeptizismus'],situationen:['Tod & Vergänglichkeit']},{id:'z375',zitat:'Du kannst jederzeit aus dem Leben scheiden – lass das bestimmen, was du tust, sagst und denkst.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Tod & Vergänglichkeit']},{id:'z376',zitat:'Ein freier Mensch denkt an nichts weniger als an den Tod, und seine Weisheit ist eine Betrachtung nicht des Todes, sondern des Lebens.',autor:'spinoza',name:'Baruch de Spinoza',themen:['Rationalismus'],situationen:['Tod & Vergänglichkeit']},{id:'z377',zitat:'Es ist nicht so, dass wir zu wenig Zeit haben, sondern dass wir zu viel davon verschwenden.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Tod & Vergänglichkeit','Stress & Überforderung']},{id:'z378',zitat:'Kein Übel kann einen guten Menschen treffen, weder im Leben noch im Tod.',autor:'sokrates',name:'Sokrates',themen:['Ethik'],situationen:['Tod & Vergänglichkeit']},{id:'z379',zitat:'Ein ganzes Leben der Philosophen ist eine Vorbereitung auf den Tod.',autor:'cicero',name:'Marcus Tullius Cicero',themen:['Stoizismus'],situationen:['Tod & Vergänglichkeit']},{id:'z380',zitat:'Wie ein Tropfen Tau, eine Wasserblase, ein Blitz in der Sommerwolke – so solltet ihr alles Bedingte betrachten.',autor:'buddha',name:'Siddhartha Gautama (Buddha)',themen:['Buddhismus'],situationen:['Tod & Vergänglichkeit']},{id:'z381',zitat:'Du hast Macht über deinen Geist – nicht über äußere Ereignisse. Erkenne das, und du wirst Stärke finden.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z382',zitat:'Verlange nicht, dass die Dinge geschehen, wie du es willst, sondern wolle, dass sie geschehen, wie sie geschehen, und du wirst gelassen sein.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z383',zitat:'Durch Nichthandeln wird nichts ungetan gelassen.',autor:'laozi',name:'Laozi',themen:['Daoismus'],situationen:['Stress & Überforderung']},{id:'z384',zitat:'Der Zwang zur Selbstoptimierung erschöpft, weil er keinen äußeren Feind mehr kennt, sondern nur noch einen inneren.',autor:'byungchulhan',name:'Byung-Chul Han',themen:['Kritische Theorie'],situationen:['Stress & Überforderung']},{id:'z385',zitat:'Wer zu viele Ziele gleichzeitig verfolgt, jagt keinem einzigen wirklich nach.',autor:'konfuzius',name:'Konfuzius',themen:['Konfuzianismus'],situationen:['Stress & Überforderung']},{id:'z386',zitat:'Wenn du den Weg beherrschst, siehst du ihn in allen Dingen.',autor:'musashi',name:'Miyamoto Musashi',themen:['Bushido'],situationen:['Stress & Überforderung']},{id:'z387',zitat:'Beeile dich, alt zu werden, solange Zeit dafür ist, meine Zeit ist nicht deine Zeit.',autor:'seneca',name:'Seneca',themen:['Stoizismus'],situationen:['Stress & Überforderung']},{id:'z388',zitat:'Erkenne dich selbst.',autor:'sokrates',name:'Sokrates',themen:['Ethik'],situationen:['Selbstzweifel & Kritik']},{id:'z389',zitat:'Blicke oft in dein eigenes Inneres, dort liegt eine Quelle des Guten, die nie versiegt, solange du in ihr gräbst.',autor:'marcaurel',name:'Marc Aurel',themen:['Stoizismus'],situationen:['Selbstzweifel & Kritik']},{id:'z390',zitat:'Werde, der du bist.',autor:'nietzsche',name:'Friedrich Nietzsche',themen:['Existentialismus'],situationen:['Selbstzweifel & Kritik']},{id:'z391',zitat:'Sich selbst zu kennen ist der Anfang aller Weisheit.',autor:'aristoteles',name:'Aristoteles',themen:['Ethik'],situationen:['Selbstzweifel & Kritik']},{id:'z392',zitat:'Handle so, dass die Maxime deines Willens jederzeit zugleich als Prinzip einer allgemeinen Gesetzgebung gelten könnte.',autor:'kant',name:'Immanuel Kant',themen:['Ethik'],situationen:['Selbstzweifel & Kritik','Entscheidungen treffen']},{id:'z393',zitat:'Zwei Dinge können durch die Seele hindurchdringen: Extreme Not oder extreme Schönheit.',autor:'weil',name:'Simone Weil',themen:['Existentialismus'],situationen:['Selbstzweifel & Kritik']},{id:'z394',zitat:'Ich mag nicht wie andere sein, aber ich bin wenigstens ich selbst.',autor:'rousseau',name:'Jean-Jacques Rousseau',themen:['Politische Philosophie'],situationen:['Selbstzweifel & Kritik']},{id:'z395',zitat:'Zeige mir nicht, was du gelesen hast, sondern was du daraus gemacht hast.',autor:'epiktet',name:'Epiktet',themen:['Stoizismus'],situationen:['Selbstzweifel & Kritik']},{id:'z396',zitat:'Individuen haben Rechte, und es gibt Dinge, die ihnen keine Person und keine Gruppe antun darf, ohne diese Rechte zu verletzen.',autor:'nozick',name:'Robert Nozick',themen:['Politische Philosophie'],situationen:['Wut & Ungerechtigkeit']},{id:'z397',zitat:'Die Vernunft ist und sollte nur die Dienerin der Leidenschaften sein.',autor:'hume',name:'David Hume',themen:['Empirismus'],situationen:['Entscheidungen treffen']},{id:'z398',zitat:'Der Geist ist bei der Geburt ein unbeschriebenes Blatt – wir formen uns selbst durch das, was wir erleben und wählen.',autor:'locke',name:'John Locke',themen:['Empirismus'],situationen:['Veränderung & Neuanfang']},{id:'z399',zitat:'Zweifel ist kein angenehmer Zustand, aber Gewissheit ist ein absurder.',autor:'voltaire',name:'Voltaire',themen:['Aufklärung'],situationen:['Sinnsuche & Zweifel']},
{"id":"z_ambedkar_1","zitat":"Ich wurde als Hindu geboren, aber ich werde nicht als Hindu sterben.","autor":"ambedkar","name":"B. R. Ambedkar","themen":["Politische Philosophie"],"situationen":["Selbstzweifel & Kritik"]}];
